import re
from functools import lru_cache

UA_RULES = [
    ("Edge", r"Edg/[\d.]+"),
    ("Chrome", r"Chrome/[\d.]+(?!.*Edg)"),
    ("Firefox", r"Firefox/[\d.]+"),
    ("Safari", r"Version/[\d.]+.*Safari"),
    ("bot", r"(bot|crawler|spider|curl|python-requests)"),
]

_COMPILED_RULES = [
    (name, re.compile(pattern, flags=re.IGNORECASE))
    for name, pattern in UA_RULES
]


def ua_family(ua: str) -> str:
    return _match(ua)


# A log file contains only a few thousand distinct UA strings, so caching
# the result per string avoids running the regexes for every request.
@lru_cache(maxsize=65536)
def _match(ua: str) -> str:
    for name, pattern in _COMPILED_RULES:
        if pattern.search(ua):
            return name
    return "other"

